/** `zoom`: how far the zooming scene travels (1 = its own size). */
export const ZOOM_FACTOR = 1.35
/** `blur`: peak blur, the Motion seam catalogue's full-frame figure (19 px at 1080p), scaled to the canvas' short edge. */
