/** `cross_zoom`: zoom at the cut. */
const CROSS_ZOOM_FACTOR = 2
/** `zoom_spin`: zoom at the half turn. */
const ZOOM_SPIN_FACTOR = 1.6
/** `stretch`: horizontal stretch at the cut. */
const STRETCH_FACTOR = 3
/** `cover` / `uncover`: how the picture underneath recedes (opacity over the black background, scale). */
