/** The parts of the segment: the two scene wrappers, the content of a clipping `to`, the colour layer. */
export type SegmentTarget = 'from' | 'to' | 'to_content' | 'dip'
export type SegmentProperty = 'opacity' | 'x' | 'y' | 'scale' | 'scale_x' | 'scale_y' | 'rotation' | 'skew_x' | 'skew_y' | 'blur'
