/** The window of a transition in its segment document (`scene-transition-timing.ts`). */
export interface TransitionRecipeWindow {
  /** Frames taken from the outgoing scene (`floor(T / 2)`, clamped): the cut is this far into the window. */
  from_frames: number
  /** The window length. */
  duration_frames: number
  /** Segment document frame of the window's first frame. */
  document_frame_offset: number
}

/** The recipe of a transition on a canvas, for one window. */
export function transitionRecipe(resolved: ResolvedTransition, canvas: Size, window: TransitionRecipeWindow): TransitionRecipe {
  const a = window.from_frames
  const total = window.duration_frames
  const start = window.document_frame_offset
  const boundary = start + a
  const span = (target: SegmentTarget, property: SegmentProperty, from: number, to: number, ease?: string): SegmentTween => ({
    target,
    property,
    from,
    to,
    start,
    duration: total,
    immediate: true,
    ...(ease !== undefined && { ease }),
  })
  /** The same, as keyframes over the whole window (their playback ease is the transition's easing). */
  const spanKeys = (target: SegmentTarget, property: SegmentProperty, frames: Keyframes, ease?: string): SegmentTween => ({
    target,
    property,
    keyframes: frames,
    start,
    duration: total,
    immediate: true,
    ...(ease !== undefined && { ease }),
  })
  /** Before the cut (the outgoing frames) and after it (the incoming frames). */
  const before = (target: SegmentTarget, property: SegmentProperty, from: number, to: number, ease?: string): SegmentTween => ({
    ...span(target, property, from, to, ease),
    duration: a,
  })
  const after = (target: SegmentTarget, property: SegmentProperty, from: number, to: number, ease?: string): SegmentTween => ({
    ...span(target, property, from, to, ease),
    start: boundary,
    duration: total - a,
    immediate: false,
  })
  const beforeKeys = (target: SegmentTarget, property: SegmentProperty, frames: Keyframes, ease?: string): SegmentTween => ({
    ...spanKeys(target, property, frames, ease),
    duration: a,
  })
  const afterKeys = (target: SegmentTarget, property: SegmentProperty, frames: Keyframes, ease?: string): SegmentTween => ({
    ...spanKeys(target, property, frames, ease),
    start: boundary,
    duration: total - a,
    immediate: false,
  })
  /** The new scene is put in place on the cut (a one-frame step): kinds that change the picture there. */
  const cut = (): SegmentTween => ({ target: 'to', property: 'opacity', from: 1, to: 1, start: boundary, duration: 1, immediate: false })
  const short = Math.min(canvas.width, canvas.height)
  const peak = (at1080: number) => q((at1080 * short) / 1080)
  const direction = resolved.direction
  const horizontal = direction === 'left' || direction === 'right'
  // The direction is where the new picture (or the wipe edge) TRAVELS: `left` enters from the right and moves left.
  const sign = direction === 'left' || direction === 'up' ? 1 : -1
  const distance = horizontal ? canvas.width : canvas.height
  const axis = horizontal ? 'x' : 'y'
  /** A turn's sense: clockwise is a positive rotation (the runtime turns like CSS). */
  const turn = direction === 'ccw' ? -1 : 1
  switch (resolved.kind) {
    case 'fade':
      return { order: ['from', 'to'], rest: { to: { opacity: 0 } }, clip: false, tweens: [span('to', 'opacity', 0, 1)] }
    case 'dip_to_color':
      return {
        order: ['from', 'to', 'dip'],
        rest: { to: { opacity: 0 }, dip: { opacity: 0 } },
        clip: false,
        tweens: [
          { target: 'dip', property: 'opacity', from: 0, to: 1, start, duration: a, immediate: true },
          // The new scene is put in place while the colour covers everything.
          { target: 'to', property: 'opacity', from: 1, to: 1, start: boundary, duration: 1, immediate: false },
          { target: 'dip', property: 'opacity', from: 1, to: 0, start: boundary, duration: total - a, immediate: false },
        ],
      }
    case 'slide':
      return {
        order: ['from', 'to'],
        rest: { to: { [axis]: sign * distance } },
        clip: false,
        tweens: [span('to', axis, sign * distance, 0)],
      }
    case 'push':
      return {
        order: ['from', 'to'],
        rest: { to: { [axis]: sign * distance } },
        clip: false,
        tweens: [span('to', axis, sign * distance, 0), span('from', axis, 0, -sign * distance)],
      }
    case 'wipe': {
      // `right`: the edge travels left to right, the window starts one canvas to the left. The window (clipping) moves one
      // way and its content the other by the same eased amount, so the new picture itself stays where it is.
      const window0 = (direction === 'right' || direction === 'down' ? -1 : 1) * distance
      return {
        order: ['from', 'to'],
        rest: { to: { [axis]: window0 }, to_content: { [axis]: -window0 } },
        clip: true,
        tweens: [span('to', axis, window0, 0), span('to_content', axis, -window0, 0)],
      }
    }
    case 'zoom':
      return direction === 'out'
        ? {
            order: ['from', 'to'],
            rest: { to: { scale: ZOOM_FACTOR, opacity: 0 } },
            clip: false,
            tweens: [span('to', 'scale', ZOOM_FACTOR, 1), span('to', 'opacity', 0, 1)],
          }
        : {
            order: ['to', 'from'],
            rest: {},
            clip: false,
            tweens: [span('from', 'scale', 1, ZOOM_FACTOR), span('from', 'opacity', 1, 0)],
          }
    case 'blur': {
      const blur = peak(BLUR_PEAK_1080P)
      return {
        order: ['from', 'to'],
        rest: { to: { opacity: 0, blur } },
        clip: false,
        tweens: [span('to', 'opacity', 0, 1), span('to', 'blur', blur, 0), span('from', 'blur', 0, blur)],
      }
    }

    // ---------------------------------------------------------------- scene-transitions@2 (batch 1a)

    case 'flash':
      // A white flash rises sharply into the cut and falls off fast after it; the new scene is put in place under it.
      return {
        order: ['from', 'to', 'dip'],
        rest: { to: { opacity: 0 }, dip: { opacity: 0 } },
        clip: false,
        dip_fill: FLASH_COLOR,
        tweens: [before('dip', 'opacity', 0, 1, 'expo.in'), cut(), after('dip', 'opacity', 1, 0, 'expo.out')],
      }
    case 'whip_pan': {
      const blur = peak(WHIP_BLUR_1080P)
      const smear = keys([0, 0], [50, blur], [100, 0])
      return {
        order: ['from', 'to'],
        rest: { to: { [axis]: sign * distance } },
        clip: false,
        tweens: [span('to', axis, sign * distance, 0), span('from', axis, 0, -sign * distance), spanKeys('from', 'blur', smear), spanKeys('to', 'blur', smear)],
      }
    }
    case 'cross_zoom': {
      // Both pictures follow ONE zoom (in to the cut, back out after it) and one blur, so the switch on the cut is seamless
      // whatever the easing; the easing paces the zoom (in-out: it rushes into the cut and settles after it).
      const zoom = keys([0, 1], [50, CROSS_ZOOM_FACTOR], [100, 1])
      const blur = keys([0, 0], [50, peak(ZOOM_BLUR_1080P)], [100, 0])
      return {
        order: ['from', 'to'],
        rest: { to: { opacity: 0 } },
        clip: false,
        tweens: [spanKeys('from', 'scale', zoom), spanKeys('to', 'scale', zoom), spanKeys('from', 'blur', blur), spanKeys('to', 'blur', blur), cut()],
      }
    }
    case 'zoom_blur': {
      const blur = peak(ZOOM_BLUR_1080P)
      return direction === 'out'
        ? {
            order: ['from', 'to'],
            rest: { to: { scale: ZOOM_FACTOR, opacity: 0, blur } },
            clip: false,
            tweens: [span('to', 'scale', ZOOM_FACTOR, 1), span('to', 'opacity', 0, 1), span('to', 'blur', blur, 0), span('from', 'blur', 0, blur)],
          }
        : {
            order: ['to', 'from'],
            rest: { to: { blur } },
            clip: false,
            tweens: [span('from', 'scale', 1, ZOOM_FACTOR), span('from', 'opacity', 1, 0), span('from', 'blur', 0, blur), span('to', 'blur', blur, 0)],
          }
    }
    case 'spin':
    case 'zoom_spin': {
      // One full turn over the window; the incoming picture is one turn behind the outgoing one (the same orientation at
      // every moment), so the scene changes at the half turn without a jump whatever the easing.
      const blur = keys([0, 0], [50, peak(SPIN_BLUR_1080P)], [100, 0])
      const tweens: SegmentTween[] = [
        span('from', 'rotation', 0, turn * 360),
        span('to', 'rotation', -turn * 360, 0),
        spanKeys('from', 'blur', blur),
        spanKeys('to', 'blur', blur),
        cut(),
      ]
      if (resolved.kind === 'zoom_spin') {
        const zoom = keys([0, 1], [50, ZOOM_SPIN_FACTOR], [100, 1])
        tweens.push(spanKeys('from', 'scale', zoom), spanKeys('to', 'scale', zoom))
      }
      return { order: ['from', 'to'], rest: { to: { opacity: 0, rotation: -turn * 360 } }, clip: false, tweens }
    }
    case 'squeeze': {
      // The edge between the two pictures travels `direction`: the old one is squeezed toward the edge it leaves by, the new
      // one stretches out of the opposite edge.
      const property = horizontal ? 'scale_x' : 'scale_y'
      const toward: Record<'left' | 'right' | 'up' | 'down', [[number, number], [number, number]]> = {
        left: [[0, 0.5], [1, 0.5]],
        right: [[1, 0.5], [0, 0.5]],
        up: [[0.5, 0], [0.5, 1]],
        down: [[0.5, 1], [0.5, 0]],
      }
      const [fromOrigin, toOrigin] = toward[(direction ?? 'left') as 'left' | 'right' | 'up' | 'down']
      return {
        order: ['from', 'to'],
        rest: { to: { [property]: 0 } },
        clip: false,
        origin: { from: fromOrigin, to: toOrigin },
        tweens: [span('from', property, 1, 0), span('to', property, 0, 1)],
      }
    }
    case 'stretch': {
      const wide = keys([0, 1], [50, STRETCH_FACTOR], [100, 1])
      const blur = keys([0, 0], [50, peak(ZOOM_BLUR_1080P)], [100, 0])
      return {
        order: ['from', 'to'],
        rest: { to: { opacity: 0 } },
        clip: false,
        tweens: [spanKeys('from', 'scale_x', wide), spanKeys('to', 'scale_x', wide), spanKeys('from', 'blur', blur), spanKeys('to', 'blur', blur), cut()],
      }
    }
    case 'cover':
      return {
        order: ['from', 'to'],
        rest: { to: { [axis]: sign * distance } },
        clip: false,
        tweens: [span('to', axis, sign * distance, 0), span('from', 'opacity', 1, COVER_DIM), span('from', 'scale', 1, COVER_SCALE)],
      }
    case 'uncover':
      // The direction is where the OLD picture travels (the moving edge); the new one waits underneath, receded.
      return {
        order: ['to', 'from'],
        rest: { to: { opacity: COVER_DIM, scale: COVER_SCALE } },
        clip: false,
        tweens: [span('from', axis, 0, -sign * distance), span('to', 'opacity', COVER_DIM, 1), span('to', 'scale', COVER_SCALE, 1)],
      }
    case 'bounce_in':
      return {
        order: ['from', 'to'],
        rest: { to: { [axis]: sign * distance } },
        clip: false,
        tweens: [span('to', axis, sign * distance, 0, 'bounce.out')],
      }
    case 'shake': {
      const amp = q(SHAKE_SHARE * short)
      return {
        order: ['from', 'to'],
        rest: { to: { opacity: 0, scale: SHAKE_SCALE } },
        clip: false,
        tweens: [
          beforeKeys('from', 'x', keys([0, 0], [20, -0.35 * amp], [40, 0.55 * amp], [60, -0.75 * amp], [80, 0.9 * amp], [100, -amp]), 'linear'),
          beforeKeys('from', 'y', keys([0, 0], [25, 0.4 * amp], [50, -0.6 * amp], [75, 0.8 * amp], [100, -amp]), 'linear'),
          before('from', 'scale', 1, SHAKE_SCALE, 'linear'),
          cut(),
          afterKeys('to', 'x', keys([0, amp], [20, -0.8 * amp], [40, 0.55 * amp], [60, -0.35 * amp], [80, 0.15 * amp], [100, 0]), 'linear'),
          afterKeys('to', 'y', keys([0, -amp], [25, 0.6 * amp], [50, -0.35 * amp], [75, 0.15 * amp], [100, 0]), 'linear'),
          after('to', 'scale', SHAKE_SCALE, 1, 'linear'),
        ],
      }
    }
    case 'diagonal_wipe': {
      // A square window turned 45° that exactly covers the canvas (side (W + H) / √2, rounded up to whole pixels) travels
      // one window side along the diagonal; its content turns and moves against it, so the picture stays put and only the
      // diagonal edge sweeps across.
      const side = Math.ceil((canvas.width + canvas.height) / Math.SQRT2)
      const [dx, dy] = direction === 'up_left' ? [-1, -1] : direction === 'up_right' ? [1, -1] : direction === 'down_left' ? [-1, 1] : [1, 1]
      const windowX = q((-side * dx) / Math.SQRT2)
      const windowY = q((-side * dy) / Math.SQRT2)
      // The content's offset in the window's turned frame (exactly minus the window's offset turned back by 45°).
      const contentX = (side * (dx + dy)) / 2
      const contentY = (side * (dy - dx)) / 2
      const tweens: SegmentTween[] = [span('to', 'x', windowX, 0), span('to', 'y', windowY, 0)]
      if (contentX !== 0) tweens.push(span('to_content', 'x', contentX, 0))
      if (contentY !== 0) tweens.push(span('to_content', 'y', contentY, 0))
      return {
        order: ['from', 'to'],
        rest: {
          to: { rotation: 45, x: windowX, y: windowY },
          to_content: { rotation: -45, ...(contentX !== 0 && { x: contentX }), ...(contentY !== 0 && { y: contentY }) },
        },
        clip: true,
        clip_box: { x: (canvas.width - side) / 2, y: (canvas.height - side) / 2, width: side, height: side },
        tweens,
      }
    }
    case 'rotate_in':
      // Clockwise: hinged at the bottom-left corner, the picture swings down from upright; counter-clockwise: bottom-right.
      return {
        order: ['from', 'to'],
        rest: { to: { rotation: -turn * ROTATE_IN_DEGREES } },
        clip: false,
        origin: { to: turn === 1 ? [0, 1] : [1, 1] },
        tweens: [span('to', 'rotation', -turn * ROTATE_IN_DEGREES, 0)],
      }
  }
}

/**
 * The Motion IR ease of a recipe tween: a kind's fixed ease when it has one, else the transition's easing; a one-frame step
 * (from == to) just sets a value.
 */
export function segmentTweenEase(tween: SegmentTween, easing: Easing): string {
  if (!('keyframes' in tween) && tween.from === tween.to) return 'linear'
  return tween.ease ?? EASING_IR[easing]
}
